import{d as c,C as t,o as m,c as u,j as a,a as r,E as s,a3 as g}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第三十六章","description":"从张歙、强弱的转化与鱼渊之喻，理解微明及王弼所说利国之器。","frontmatter":{"title":"道德经第三十六章","description":"从张歙、强弱的转化与鱼渊之喻，理解微明及王弼所说利国之器。","category":"guide","aliases":["道德经第三十六章","老子第三十六章","dao de jing chapter 36"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-36.md","filePath":"daoism/dao-de-jing/chapter-36.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-36.md"},y=c({...p,setup(b){const o=[{id:"opposing-movements",label:"将欲歙之，必固张之",showLabel:!0,sentences:[["将欲",{text:"歙",glossary:"xi"},"之，必",{text:"固",glossary:"gu"},{text:"张",glossary:"zhang"},"之；将欲",{text:"弱",glossary:"ruo"},"之，必固",{text:"强",glossary:"qiang"},"之；将欲",{text:"废",glossary:"fei"},"之，必固",{text:"兴",glossary:"xing"},"之；将欲取之，必固",{text:"与",glossary:"yu"},"之。"]],note:["【白话】想要收敛它，必先暂且让它张开；想要削弱它，必先暂且让它强大；想要使它衰废，必先暂且让它兴起；想要取走它，必先暂且给予它。四句都把趋向目标与眼前相反的动作并列。","【王弼注择要】「将欲除强梁去暴乱，当以此四者因物之性，令其自戮。」王弼将四者放在消解强暴的政治处境中，包含借其发展而使其自败的谋略意味。","【读法】固本页取姑且、暂且义，白话用先暂且说明句势；也有作固然、必然等解释的取径。张歙强弱的转化不能脱离条件，王注的政治谋略也不能直接变成人际操控的通则。"]},{id:"subtle-discernment",label:"是谓微明",showLabel:!0,sentences:[["是谓",{text:"微明",glossary:"weiming"},"。"]],note:["【白话】这称作对隐微变化的明察：在张大、强盛的表象中，看到它可能转向收敛、衰弱的条件，而不只盯着当前的强弱胜负。","【王弼注择要】「足其张，令之足而又求其张，则众所歙也。」注以张之过度而招致众人收敛说明转折；这有具体条件，并非越强便会立即自行败亡。","【读法】微明承接四者的关系，既涉及隐微的判断，也涉及王注所说因物之性；不能把所有失败都倒推成事先安排好的结果。"]},{id:"softness-and-strength",label:"柔弱胜刚强",showLabel:!0,sentences:[[{text:"柔弱",glossary:"rouruo"},"胜刚强。"]],note:["【白话】柔顺、不以刚强相争的一面，能够胜过刚硬强横的一面。接在微明之后，是提醒力量的作用不能只按外表强硬来衡量。","【读法】这一句在所据录文此处未见独立逐句王注，本页不补造。柔弱与刚强须连全章的转化和治理语境来读，不表示任何处境都应忍受伤害或放弃必要行动。"]},{id:"fish-and-the-depths",label:"鱼不可脱于渊",showLabel:!0,sentences:[["鱼不可脱于",{text:"渊",glossary:"yuan"},"，"]],note:["【白话】鱼不可以离开深水。鱼赖以生存的条件，说明事物不能只凭眼前的活动与力量，便脱离成全自身的根本。","【王弼注择要】「鱼脱于渊，则必见失矣。」注随即将鱼之失渊与利国器而立刑以示人的失误对照，鱼渊之喻因而与治理相连。","【读法】渊在这里是深水、深潭，不直接套用第八章心善渊的深静义。本句保留原有逗号，须接下段读完。"]},{id:"instruments-of-governance",label:"国之利器不可以示人",showLabel:!0,sentences:[["国之",{text:"利器",glossary:"liqi"},"不可以",{text:"示",glossary:"shi"},"人。"]],note:["【白话】有利于国家治理的根本凭借，不可以作为炫示于人的手段。依王弼，这种凭借在于顺万物之性，使它们各得其所；一旦改以刑罚威示，就会失去原来的作用。","【王弼注择要】「利器，利国之器也。」注又说「器不可睹而物各得其所」，并以「示人者，任刑也」解释示人，落点在依仗刑罚的治理。","【读法】利器常见另有兵器、权柄等读法；本页明确采用王弼取径，不把不示人扩写成现代一切公共事务都应保密的主张。"]}],n=[{id:"xi",term:"歙",sense:1},{id:"gu",term:"固",sense:1},{id:"zhang",term:"张",sense:1},{id:"ruo",term:"弱",sense:1},{id:"qiang",term:"强",sense:4,pinyin:"qiáng"},{id:"fei",term:"废",sense:2},{id:"xing",term:"兴",sense:1},{id:"yu",term:"与",sense:2},{id:"weiming",term:"微明",sense:1},{id:"rouruo",term:"柔弱",sense:1},{id:"yuan",term:"渊",sense:2},{id:"liqi",term:"利器",sense:1},{id:"shi",term:"示",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return m(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第三十六章",tabindex:"-1"},[r("道德经第三十六章 "),a("a",{class:"header-anchor",href:"#道德经第三十六章","aria-label":'Permalink to "道德经第三十六章"'},"​")],-1)),s(i,{title:"怎样读张歙之间的转化与微明",summary:"本章以四组相反相成的动作起笔，接着说微明、柔弱胜刚强，最后转到鱼不可脱渊与国之利器。王弼将前段放在除强暴的政治处境中，末段则以顺物之性、少任刑说明利国之器。",points:[{label:"先读",text:"先逐一辨张与歙、强与弱、兴与废、与与取的方向。"},{label:"再辨",text:"王注有因物之性、令其自戮的谋略意味，须说明其历史语境。"},{label:"后看",text:"鱼离不开渊，治理也有不可失的根本；末句循王注辨器与任刑。"}],hint:"歙读 xī，取收敛、合拢义；固本页取姑且、暂且义；强之的强读 qiáng，取使之强大义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[r("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),s(l,{sections:o,glossary:n}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[r("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),s(d,{lines:[{text:"将欲歙之，必固张之；将欲弱之，必固强之；将欲废之，必固兴之；将欲取之，必固与之。",tone:"先辨方向，再看转折",guide:"四对动作都涉及目标与眼前发展之间的反向关系；王弼把它放在除强暴的政治语境中。"},{text:"是谓微明。柔弱胜刚强。",tone:"看到表象之外的条件",guide:"强盛未必足以持久，柔顺也未必没有作用；判断须连具体条件。"},{text:"鱼不可脱于渊，国之利器不可以示人。",tone:"守住成全作用的根本",guide:"依王弼，从鱼失渊读到任刑之失，而不是将末句缩成保密格言。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[r("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(h,{items:n}),e[4]||(e[4]=g('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-四组相反动作为什么接到鱼和利器" tabindex="-1">象：四组相反动作为什么接到鱼和利器？ <a class="header-anchor" href="#象-四组相反动作为什么接到鱼和利器" aria-label="Permalink to &quot;象：四组相反动作为什么接到鱼和利器？&quot;">​</a></h3><p>前半章提示张歙、强弱会在一定条件下转化，后半章则由鱼必须有所依，转入治理应守的根本。贯通处在于：不能只看表面力量与眼前动作，还要看它们凭什么成立、何时反而受损。</p><h3 id="理-这章是在说规律-还是在说谋略" tabindex="-1">理：这章是在说规律，还是在说谋略？ <a class="header-anchor" href="#理-这章是在说规律-还是在说谋略" aria-label="Permalink to &quot;理：这章是在说规律，还是在说谋略？&quot;">​</a></h3><p>文字有主动的将欲、必固，王弼又明说除强梁、去暴乱及令其自戮，确有政治谋略取向；同时，注以过度求张而招众歙解释转化的条件。本页保留两层，不把谋略淡化为无意志的循环，也不把它推广成操纵任何人的准则。</p><h3 id="用-今天可以怎样借鉴微明" tabindex="-1">用：今天可以怎样借鉴微明？ <a class="header-anchor" href="#用-今天可以怎样借鉴微明" aria-label="Permalink to &quot;用：今天可以怎样借鉴微明？&quot;">​</a></h3><p>可以观察一项力量的成立条件、扩张代价和反作用，避免只因眼下强势就不断加码。用于合作时，应把这些观察转为诚实的边界与反馈，不能以本章为隐瞒意图、故意诱人失败的理由。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>在加码之前看反作用。</strong> 一项要求不断增强时，检视资源、关系与承受能力是否跟得上。表面推进更快，可能同时在积累反弹。</p><p><strong>辨认工作赖以成立的条件。</strong> 工具、权力与规则之所以有效，常依赖信任、能力和适当环境。检视这些条件，比只强化外在威势更有助于维持作用。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我正在加大哪一种力量？它依赖的条件是否仍在，又是否已经引出我没有认真听见的反作用？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本站保留「将欲取之」，所据 HFL 录文作「将欲夺之」；其余原句及标点沿本站保留。</li><li>固取姑且、暂且义，歙读 xī；弱之、强之、废之均按使动理解，与取给予义。字词取径与王弼古注分别标明。</li><li>王注前段有除强暴、因物之性而令其自败的政治谋略意味；末句利器依利国之器、示人依任刑解释，另提示兵器与权柄等读法。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_002.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷二 HFL 本电子录文，011b–012a</a>。</p><p>字词参考：<a href="https://www.zdic.net/hans/%E5%9B%BA" target="_blank" rel="noreferrer">汉典「固」姑且、暂且义</a>、<a href="https://www.zdic.net/hans/%E6%AD%99" target="_blank" rel="noreferrer">「歙」xī 收敛义</a>。</p>',16))])}}});export{_ as __pageData,y as default};
